var i=[{title:`Πώς λειτουργεί η αντίσταση`,text:`Ένας αλτήρας ζυγίζει το ίδιο σε κάθε σημείο, αλλά η αντίσταση του λάστιχου εξαρτάται από το πόσο τεντώνεται, πόσο χοντρό είναι και ποιο προϊόν είναι. Ένα μακρύτερο ή χοντρότερο λάστιχο δεν ισοδυναμεί με ορισμένο βάρος, και οι χρωματικοί κωδικοί διαφέρουν ανάμεσα στους κατασκευαστές. Το σημείο της κίνησης όπου η αντίσταση είναι μεγαλύτερη μπορεί επίσης να διαφέρει από μια άσκηση με ελεύθερα βάρη.`},{title:`Επιλογές ασκήσεων`,text:`Τα λάστιχα δουλεύουν καλά για κωπηλασίες, πιέσεις, πλάγιες ανυψώσεις, πιέσεις Pallof και pulldowns από σωστά εγκατεστημένο σημείο αγκύρωσης. Ένα κυκλικό λάστιχο γύρω από τα γόνατά σας προσθέτει ελαφριά αντίσταση σε ασκήσεις ισχίου. Για ορισμένες κινήσεις μπορείτε να πατήσετε πάνω στο λάστιχο ως απλή αγκύρωση, αρκεί να μη γλιστρήσει και να μη τιναχτεί προς τα πάνω.`},{title:`Ελέγξτε και αγκυρώστε με ασφάλεια`,text:`Πριν από κάθε συνεδρία, ελέγξτε για ρωγμές, λεπτά σημεία, σκισίματα, χαλασμένες λαβές και φθαρμένους συνδέσμους. Χρησιμοποιήστε ειδικά κατασκευασμένο σημείο αγκύρωσης όπως ορίζει ο κατασκευαστής και βεβαιωθείτε ότι δεν μπορεί να λυθεί. Μην τεντώνετε υπερβολικά το λάστιχο, μην το αφήνετε να τρίβεται σε αιχμηρές ακμές και μη βάζετε το πρόσωπό σας στη διαδρομή που θα ακολουθούσε αν τιναχτεί πίσω. Ένα λάστιχο που γλιστρά μπορεί να προκαλέσει τραυματισμούς στα μάτια και άλλη βλάβη.`},{title:`Πρόοδος και καταγραφή`,text:`Προσθέστε ελεγχόμενες επαναλήψεις, περάστε σε λάστιχο με περισσότερη αντίσταση ή αλλάξτε τη στάση ή την απόστασή σας από το σημείο αγκύρωσης, αρκεί η νέα διάταξη να μένει ασφαλής. Η τάση αλλάζει με το μήκος, οπότε καταγράψτε το λάστιχο ή τη διάταξη που χρησιμοποιήσατε· το χρώμα του δεν θα σας δώσει ακριβές βάρος σε κιλά. Μην αυξάνετε απότομα ταυτόχρονα την τάση και το εύρος του λάστιχου.`},{title:`Χρήση του TrainUp`,text:`Στο Profile, καταχωρίστε την αντίσταση των λάστιχων που έχετε. Μετρήστε τα λάστιχά σας ως διαθέσιμα μόνο όταν έχετε ασφαλές σημείο αγκύρωσης για την άσκηση που σχεδιάζετε. Αν δεν μπορείτε να επιβεβαιώσετε το σημείο αγκύρωσης, την κατάσταση του λάστιχου ή τον χώρο σας, διαλέξτε μια ασφαλέστερη εναλλακτική.`}];var l=[{label:`NHS: ασφάλεια των λάστιχων αντίστασης`,url:`https://abuhb.nhs.wales/files/patient-information-leaflets1/physiotherapy/safety-advice-when-exercising-with-resistance-bands-or-tubing-piu1332/`},{label:`Βιβλιοθήκη ασκήσεων του ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Θέση του ACSM για το 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:i,sources:l};export{s as default,i as sections,l as sources};